import re
import unicodedata


def slugify(s):
    s = unicodedata.normalize('NFKD', s.lower())
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        elif unicodedata.category(ch)[0] == 'M':
            # drop combining marks left over from decomposition (e.g. 'õ' -> 'o' + tilde)
            continue
        else:
            out.append('-')
    return re.sub(r'-+', '-', ''.join(out)).strip('-')

import unicodedata


def slugify(s):
    s = s.lower()
    # Decompose and drop combining marks so e.g. 'õ' becomes 'o'.
    s = unicodedata.normalize('NFD', s)
    s = ''.join(ch for ch in s if not unicodedata.combining(ch))
    out = []
    for ch in s:
        if ch.isalnum():
            out.append(ch)
        elif out and out[-1] != '-':
            out.append('-')
    while out and out[-1] == '-':
        out.pop()
    return ''.join(out)

